css:
.bg__lead{font-family:var(--os-font-heading);font-size:clamp(1.5rem,1rem + 1.8vw,2.3rem);line-height:1.25;letter-spacing:-.01em;max-width:36ch;margin:0 0 1rem;color:var(--os-color-heading)}
.bg__note{max-width:62ch;color:var(--os-color-text-muted);margin:0}
.bg__bar{display:flex;height:3.2rem;border-radius:999px;overflow:hidden;margin:1.6rem 0 .8rem;gap:3px}
.bg__s{display:block;min-width:0;flex:1}
.bg__c0{background:#6b8e36}.bg__c1{background:#a9a72f}.bg__c2{background:#eec02b}
.bg__key{display:flex;flex-wrap:wrap;gap:.6rem 2rem;font-size:.98rem;margin:0 0 2.2rem;padding:0;list-style:none}
.bg__key li{display:flex;align-items:center;gap:.5rem}
.bg__key i{width:.9rem;height:.9rem;border-radius:999px;display:block}
.bg__tier{padding:1.5rem 0;border-top:1px solid rgba(21,38,26,.22);display:grid;gap:.5rem 3rem}
@media (min-width:1200px){.bg__tier{grid-template-columns:minmax(0,15rem) minmax(0,1fr)}}
.bg__h{margin:0}
.bg__tot{color:var(--os-color-text-muted);margin:.2rem 0 0;font-size:1rem}
.bg__dl{margin:0}
.bg__row{display:grid;gap:.2rem 1.5rem;padding:.9rem 0;border-bottom:1px solid rgba(21,38,26,.22)}
.bg__row:last-child{border-bottom:0}
.bg__row dt{font-weight:700}
.bg__row dd{margin:0;color:var(--os-color-text-muted);font-size:1.02rem}
.bg__row .bg__amt{font-variant-numeric:tabular-nums;font-weight:700;color:var(--os-color-heading);grid-row:1}
@media (min-width:768px){.bg__row{grid-template-columns:minmax(0,1fr) 8rem}.bg__row .bg__amt{text-align:right;grid-column:2}.bg__row dt,.bg__row dd{grid-column:1}}
.bg__fn{font-size:.92rem;color:var(--os-color-text-muted);max-width:62ch;margin:.4rem 0 0}
